CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, phone TEXT UNIQUE NOT NULL, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, avatar_url TEXT, bio TEXT DEFAULT '', is_premium INTEGER DEFAULT 0, is_business INTEGER DEFAULT 0, is_verified INTEGER DEFAULT 0, language TEXT DEFAULT 'si', last_seen INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS contacts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, contact_id TEXT NOT NULL, nickname TEXT, is_blocked INTEGER DEFAULT 0, created_at INTEGER NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(contact_id) REFERENCES users(id), UNIQUE(user_id,contact_id));
CREATE TABLE IF NOT EXISTS chats (id TEXT PRIMARY KEY, type TEXT NOT NULL DEFAULT 'direct', name TEXT, avatar_url TEXT, description TEXT DEFAULT '', created_by TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS chat_participants (id TEXT PRIMARY KEY, chat_id TEXT NOT NULL, user_id TEXT NOT NULL, role TEXT DEFAULT 'member', joined_at INTEGER NOT NULL, last_read_message_id TEXT, FOREIGN KEY(chat_id) REFERENCES chats(id), FOREIGN KEY(user_id) REFERENCES users(id), UNIQUE(chat_id,user_id));
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, chat_id TEXT NOT NULL, sender_id TEXT NOT NULL, text TEXT, message_type TEXT DEFAULT 'text', media_url TEXT, media_thumbnail TEXT, media_size INTEGER, reply_to_id TEXT, status TEXT DEFAULT 'sent', is_edited INTEGER DEFAULT 0, is_deleted INTEGER DEFAULT 0, created_at INTEGER NOT NULL, edited_at INTEGER, FOREIGN KEY(chat_id) REFERENCES chats(id), FOREIGN KEY(sender_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS message_status (id TEXT PRIMARY KEY, message_id TEXT NOT NULL, user_id TEXT NOT NULL, status TEXT NOT NULL, timestamp INTEGER NOT NULL, FOREIGN KEY(message_id) REFERENCES messages(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_messages_chat_id ON messages(chat_id,created_at);
CREATE INDEX IF NOT EXISTS idx_chat_participants ON chat_participants(user_id);
CREATE INDEX IF NOT EXISTS idx_contacts_user ON contacts(user_id);
CREATE INDEX IF NOT EXISTS idx_users_username ON users(username);
